{
  "findings": [
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket lacks versioning",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "Versioning is not enabled on the S3 bucket. Without versioning, accidental deletions or overwrites of objects cannot be recovered, which poses a risk to data integrity."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "financials" {
  bucket        = "${local.resource_prefix.value}-financials"
  acl           = "private"
  force_destroy = true
  tags = merge({
    Name        = "${local.resource_prefix.value}-financials"
    Environment = local.resource_prefix.value
    }, {
  })
}

resource "aws_s3_bucket_versioning" "financials_versioning" {
  bucket = aws_s3_bucket.financials.id
  versioning_configuration {
    status = "Enabled"
  }
}",
  "fix_summary": "Enabled versioning for the S3 bucket by adding an `aws_s3_bucket_versioning` resource to ensure data integrity and recovery in case of accidental deletions or overwrites."
}
